H.background();
const w = H.W, h = H.H;
const A = Math.max(0.05, P.A), f = Math.max(0.1, P.f), lambda = Math.max(0.5, P.lambda);
const k = 2 * Math.PI / lambda, omega = 2 * Math.PI * f;
H.text("Transverse vs Longitudinal waves", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Same wave equation y/s = A sin(k x - w t); the difference is the DIRECTION particles move", 24, 52, { color: H.colors.sub, size: 12 });
// ---- Transverse (top): particles displace PERPENDICULAR to travel (vertical) ----
const tyMid = h * 0.36, xL = 70, xR = w - 40, span = xR - xL;
H.text("Transverse  (e.g. light, string)  —  particle motion is up/down", xL, tyMid - 70, { color: H.colors.accent, size: 13, weight: 600 });
H.line(xL, tyMid, xR, tyMid, { color: H.colors.grid, width: 1, dash: [3, 5] });
const N = 26;
for (let i = 0; i < N; i++) {
  const xWave = (i / (N - 1)) * (span / 50) * lambda * 0 + i * 0.4; // wave-space coordinate
  const px = xL + (i / (N - 1)) * span;
  const disp = A * Math.sin(k * xWave - omega * t);
  const py = tyMid - disp * 42;
  H.circle(px, py, 4, { fill: H.colors.accent });
  if (i === 18) {
    H.arrow(px, tyMid, px, py, { color: H.colors.warn, width: 2, head: 7 });
  }
}
H.arrow(xR - 90, tyMid - 64, xR - 20, tyMid - 64, { color: H.colors.good, width: 2 });
H.text("travel", xR - 86, tyMid - 70, { color: H.colors.good, size: 11 });
// ---- Longitudinal (bottom): particles displace ALONG travel (horizontal) ----
const lyMid = h * 0.78;
H.text("Longitudinal  (e.g. sound)  —  particle motion is back/forth, making compressions", xL, lyMid - 56, { color: H.colors.accent2, size: 13, weight: 600 });
for (let i = 0; i < N; i++) {
  const xWave = i * 0.4;
  const px0 = xL + (i / (N - 1)) * span;
  const disp = A * Math.sin(k * xWave - omega * t);
  const px = px0 + disp * 18; // displaced ALONG x
  H.line(px, lyMid - 22, px, lyMid + 22, { color: H.colors.accent2, width: 2 });
  if (i === 18) {
    H.arrow(px0, lyMid + 34, px, lyMid + 34, { color: H.colors.warn, width: 2, head: 7 });
  }
}
H.arrow(xR - 90, lyMid - 40, xR - 20, lyMid - 40, { color: H.colors.good, width: 2 });
H.text("travel", xR - 86, lyMid - 46, { color: H.colors.good, size: 11 });
H.text("A = " + A.toFixed(2) + " m   f = " + f.toFixed(1) + " Hz   lambda = " + lambda.toFixed(1) + " m   v = " + (f * lambda).toFixed(1) + " m/s", 24, h - 16, { color: H.colors.sub, size: 13 });
